export function parseRouteYieldInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRouteYieldInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    // TODO: Coded error.
    throw new Error("Not enough accounts");
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      authority: getNextAccount(),
      adminRecord: getNextAccount(),
      vault: getNextAccount(),
      source: getNextAccount(),
      escrow: getNextAccount(),
      platformTreasury: getNextAccount(),
      paymentMint: getNextAccount(),
      paymentTokenProgram: getNextAccount(),
      platform: getNextAccount(),
    },
    data: getRouteYieldInstructionDataDecoder().decode(instruction.data),
  };
}
